use std::ffi::OsString;
use std::os::unix::ffi::OsStringExt;
use std::process::Command;

fn to_lower(s: &[u8]) -> Vec<u8> {
    s.iter().map(|&b| if b >= b'A' && b <= b'Z' { b + 32 } else { b }).collect()
}
fn strip_xn(s: &[u8]) -> Vec<u8> {
    if s.len() >= 4 && &s[0..4] == b"xn--" { s[4..].to_vec() } else { s.to_vec() }
}
fn predict(d: &[u8]) -> Vec<u8> {
    let mut o: Vec<u8> = Vec::new();
    let mut r1 = b"xn--".to_vec(); r1.extend_from_slice(&to_lower(d));
    let r2 = strip_xn(&r1);
    let mut r3 = b"xn--".to_vec(); r3.extend_from_slice(d);
    let r4 = strip_xn(&r3);
    let r5 = !d.is_empty() && d.len() <= 255;
    let r6 = true;
    let r7 = d.iter().all(|&b| b < 0x80);
    let r8 = d.iter().any(|&b| b >= 0x80);
    let r9 = b"mixedcase".to_vec();
    let r10 = to_lower(d);
    let r11: Vec<u8> = match d.iter().rposition(|&b| b == b'.') {
        Some(i) => d[i+1..].to_vec(),
        None => d.to_vec(),
    };
    let r12 = d.iter().filter(|&&b| b == b'.').count() + 1;
    for part in [r1, r2, r3, r4] { o.extend_from_slice(&part); o.push(b'\n'); }
    for b in [r5, r6, r7, r8] { o.extend_from_slice(if b { b"1" } else { b"0" }); o.push(b'\n'); }
    o.extend_from_slice(&r9); o.push(b'\n');
    o.extend_from_slice(&r10); o.push(b'\n');
    o.extend_from_slice(&r11); o.push(b'\n');
    o.extend_from_slice(r12.to_string().as_bytes()); o.push(b'\n');
    o
}

fn desc(v: &[u8]) -> String {
    let mut s = String::new();
    let show: Vec<u8> = if v.len() > 60 { v[..30].to_vec() } else { v.to_vec() };
    for &b in &show {
        if b >= 0x20 && b < 0x7f { s.push(b as char) } else { s.push_str(&format!("\\x{:02x}", b)) }
    }
    if v.len() > 60 { s.push_str(&format!("...[len={}]", v.len())); } else { s.push_str(&format!(" [len={}]", v.len())); }
    s
}

fn rep(b: &[u8], n: usize) -> Vec<u8> { b.iter().cloned().cycle().take(n).collect() }

fn main() {
    let bin = "/workspace/dataset/test12_executable";
    let mut probes: Vec<(String, Vec<u8>)> = Vec::new();
    let mut add = |probes: &mut Vec<(String, Vec<u8>)>, name: &str, v: Vec<u8>| {
        probes.push((name.to_string(), v));
    };

    // 1) length sweep single label 'a'
    for n in 0..=6 { add(&mut probes, &format!("a x{}", n), rep(b"a", n)); }
    for n in 248..=262 { add(&mut probes, &format!("a x{}", n), rep(b"a", n)); }
    // uppercase sweep near boundary
    for n in 253..=258 { add(&mut probes, &format!("A x{}", n), rep(b"A", n)); }

    // 2) shapes at boundary lengths
    for n in [252usize,253,254,255,256,257,258] {
        add(&mut probes, &format!("dots x{}", n), rep(b".", n));
        add(&mut probes, &format!("spaces x{}", n), rep(b" ", n));
        add(&mut probes, &format!("trailing-dot {}", n), { let mut v = rep(b"a", n-1); v.push(b'.'); v });
        add(&mut probes, &format!("leading-dot {}", n), { let mut v = vec![b'.']; v.extend(rep(b"a", n-1)); v });
        add(&mut probes, &format!("alt a. {}", n), rep(b"a.", n));
        add(&mut probes, &format!("0xFF x{}", n), rep(&[0xFFu8], n));
        add(&mut probes, &format!("0x80 x{}", n), rep(&[0x80u8], n));
        add(&mut probes, &format!("0x01 x{}", n), rep(&[0x01u8], n));
        add(&mut probes, &format!("newlines x{}", n), rep(b"\n", n));
        add(&mut probes, &format!("hyphens x{}", n), rep(b"-", n));
        add(&mut probes, &format!("emptylabels a..b {}", n), { let mut v = rep(b"a..", n-1); v.truncate(n-1); v.push(b'b'); v });
    }

    // 3) 63-byte labels (RFC-legal shapes) totalling near 255
    for k in 3..=5usize {
        for extra in 0..3usize {
            let mut v: Vec<u8> = Vec::new();
            for i in 0..k { if i > 0 { v.push(b'.'); } v.extend(rep(b"x", 63)); }
            v.extend(rep(b"y", extra));
            let n = v.len();
            add(&mut probes, &format!("{}x63labels+{} len{}", k, extra, n), v);
        }
    }
    // 64-byte label variants (over per-label limit) but total <=255
    for k in 1..=3usize {
        let mut v: Vec<u8> = Vec::new();
        for i in 0..k { if i > 0 { v.push(b'.'); } v.extend(rep(b"z", 64)); }
        let n = v.len();
        add(&mut probes, &format!("{}x64labels len{}", k, n), v);
    }
    // single 64/65/100/253/254 label + .com
    for l in [64usize, 65, 100, 200, 250, 251, 252] {
        let mut v = rep(b"q", l); v.extend_from_slice(b".com");
        let n = v.len();
        add(&mut probes, &format!("q{}+.com len{}", l, n), v);
    }

    // 4) multibyte UTF-8 straddling
    let eacute: &[u8] = &[0xC3, 0xA9];
    for k in [126usize, 127, 128, 129] {
        let v = rep(eacute, k*2);
        let n = v.len();
        add(&mut probes, &format!("eacute x{} len{}", k, n), v);
    }
    // 127 eacute + 1 ascii = 255
    { let mut v = rep(eacute, 254); v.push(b'a'); add(&mut probes, "127eacute+a len255", v); }
    { let mut v = rep(eacute, 254); v.extend_from_slice(b"ab"); add(&mut probes, "127eacute+ab len256", v); }
    let euro: &[u8] = &[0xE2, 0x82, 0xAC];
    for k in [84usize, 85, 86] {
        let v = rep(euro, k*3);
        let n = v.len();
        add(&mut probes, &format!("euro x{} len{}", k, n), v);
    }
    { let mut v = rep(euro, 255); add(&mut probes, "euro85 len255", v.clone()); v.push(b'a'); add(&mut probes, "euro85+a len256", v); }
    let emoji: &[u8] = &[0xF0, 0x9F, 0x98, 0x80];
    for k in [62usize, 63, 64, 65] {
        let v = rep(emoji, k*4);
        let n = v.len();
        add(&mut probes, &format!("emoji x{} len{}", k, n), v);
    }
    { let mut v = rep(emoji, 252); v.extend_from_slice(b"abc"); add(&mut probes, "emoji63+abc len255", v); }
    { let mut v = rep(emoji, 252); v.extend_from_slice(b"abcd"); add(&mut probes, "emoji63+abcd len256", v); }
    // truncated / invalid utf8 straddling the boundary
    { let mut v = rep(b"a", 254); v.push(0xC3); add(&mut probes, "254a+0xC3 len255", v); }
    { let mut v = rep(b"a", 255); v.push(0xC3); add(&mut probes, "255a+0xC3 len256", v); }
    { let mut v = rep(b"a", 253); v.extend_from_slice(&[0xE2, 0x82]); add(&mut probes, "253a+E282 len255", v); }
    { let mut v = rep(b"a", 254); v.extend_from_slice(&[0xE2, 0x82]); add(&mut probes, "254a+E282 len256", v); }
    { let mut v = rep(b"a", 252); v.extend_from_slice(&[0xF0, 0x9F, 0x98]); add(&mut probes, "252a+F09F98 len255", v); }
    { let mut v = rep(b"a", 253); v.extend_from_slice(&[0xF0, 0x9F, 0x98]); add(&mut probes, "253a+F09F98 len256", v); }
    // continuation bytes only
    for n in [254usize,255,256] { add(&mut probes, &format!("0xBF x{}", n), rep(&[0xBFu8], n)); }
    // overlong/surrogate-ish sequences
    { let v = rep(&[0xEDu8,0xA0,0x80], 255); add(&mut probes, "surrogate-ish len255", v); }
    { let v = rep(&[0xEDu8,0xA0,0x80], 258); add(&mut probes, "surrogate-ish len258", v); }
    { let v = rep(&[0xC0u8,0x80], 254); add(&mut probes, "overlong C080 len254", v); }
    { let v = rep(&[0xC0u8,0x80], 256); add(&mut probes, "overlong C080 len256", v); }
    { let v = rep(&[0xF4u8,0x90,0x80,0x80], 256); add(&mut probes, "beyond-U10FFFF len256", v); }

    // 5) mixed high/ascii, dotted multibyte
    { let mut v: Vec<u8> = Vec::new(); for _ in 0..85 { v.extend_from_slice(eacute); v.push(b'.'); } v.truncate(255); add(&mut probes, "eacute-dot len255", v); }
    { let mut v: Vec<u8> = Vec::new(); for _ in 0..86 { v.extend_from_slice(eacute); v.push(b'.'); } v.truncate(256); add(&mut probes, "eacute-dot len256", v); }
    { let mut v: Vec<u8> = Vec::new(); for i in 0..255 { v.push(if i%2==0 {0x80 + (i as u8 % 0x7f)} else {b'A' + (i as u8 % 26)}); } add(&mut probes, "mixed hi/upper len255", v); }
    { let mut v: Vec<u8> = Vec::new(); for i in 0..256 { v.push(if i%2==0 {0x80 + (i as u8 % 0x7f)} else {b'A' + (i as u8 % 26)}); } add(&mut probes, "mixed hi/upper len256", v); }
    // all byte values 1..=255 in one string (len 255)
    { let v: Vec<u8> = (1u16..=255).map(|b| b as u8).collect(); add(&mut probes, "all bytes 1..255 len255", v); }
    { let mut v: Vec<u8> = (1u16..=255).map(|b| b as u8).collect(); v.push(b'a'); add(&mut probes, "all bytes 1..255 +a len256", v); }
    { let mut v: Vec<u8> = (1u16..=255).map(|b| b as u8).collect(); v.reverse(); add(&mut probes, "all bytes 255..1 len255", v); }

