    for n in [259usize, 260, 300, 511, 512, 1000, 1023, 4096, 8192, 65535, 65536, 131072] {
        add(&mut probes, &format!("a x{}", n), rep(b"a", n));
    }
    { let mut v = rep(b"AB.", 999); v.extend_from_slice(b"COM"); add(&mut probes, "AB. x999 + COM", v); }
    { let v = rep(b".", 1000); add(&mut probes, "dots x1000", v); }
    { let mut v = rep(b"x", 1000); v.extend_from_slice(b".TLDupper"); add(&mut probes, "1000x + .TLDupper", v); }
    { let mut v = rep(eacute, 1000); v.extend_from_slice(b".Ünicode"); add(&mut probes, "500eacute + .Unicode", v); }
    { let mut v = rep(b"a", 500); v.push(b'.'); add(&mut probes, "500a + trailing dot", v); }
    { let mut v = vec![b'.']; v.extend(rep(b"Z", 400)); add(&mut probes, "dot + 400Z", v); }
    { let v = rep(&[0xFFu8], 1000); add(&mut probes, "0xFF x1000", v); }
    { let v = rep(b" ", 1000); add(&mut probes, "spaces x1000", v); }
    { let mut v = rep(b"a", 300); v.extend_from_slice(b"\n\n"); v.extend(rep(b"b", 10)); add(&mut probes, "300a + nl + 10b", v); }
    { let mut v = rep(b"XN--", 100); v.extend(rep(b"y", 100)); add(&mut probes, "XN-- x100 + 100y", v); }
    { let mut v = b"xn--".to_vec(); v.extend(rep(b"a", 300)); add(&mut probes, "xn-- + 300a", v); }
    { let mut v = b"xn--".to_vec(); v.extend(rep(b"a", 251)); add(&mut probes, "xn-- + 251a len255", v); }
    { let mut v = b"xn--".to_vec(); v.extend(rep(b"a", 252)); add(&mut probes, "xn-- + 252a len256", v); }
    { let mut v = b"XN--".to_vec(); v.extend(rep(b"A", 252)); add(&mut probes, "XN-- + 252A len256", v); }

    // 7) trailing/leading whitespace at boundary (trim probes)
    { let mut v = rep(b"a", 255); v.push(b' '); add(&mut probes, "255a + space len256", v); }
    { let mut v = rep(b"a", 255); v.extend_from_slice(b"  "); add(&mut probes, "255a + 2sp len257", v); }
    { let mut v = vec![b' ']; v.extend(rep(b"a", 255)); add(&mut probes, "space + 255a len256", v); }
    { let mut v = rep(b"a", 255); v.push(b'\t'); add(&mut probes, "255a + tab len256", v); }
    { let mut v = rep(b"a", 255); v.push(b'\n'); add(&mut probes, "255a + nl len256", v); }
    { let mut v = rep(b"a", 255); v.push(b'\r'); add(&mut probes, "255a + cr len256", v); }
    { let mut v = rep(b"a", 255); v.push(b'.'); add(&mut probes, "255a + dot len256", v); }
    { let mut v = rep(b"a", 255); v.extend_from_slice(b".."); add(&mut probes, "255a + 2dots len257", v); }
    { let mut v = rep(b"a", 254); v.push(b'.'); v.push(b'.'); add(&mut probes, "254a + 2dots len256", v); }
    { let mut v = rep(b"a", 256); v.push(b'.'); add(&mut probes, "256a + dot len257", v); }

    // 8) exactly-boundary with realistic domain shapes
    { let mut v: Vec<u8> = Vec::new(); while v.len() < 251 { v.extend_from_slice(b"ab."); } v.truncate(251); v.extend_from_slice(b".com"); let n=v.len(); add(&mut probes, &format!("ab.-pattern+.com len{}", n), v); }
    { let mut v: Vec<u8> = Vec::new(); while v.len() < 252 { v.extend_from_slice(b"ab."); } v.truncate(252); v.extend_from_slice(b".com"); let n=v.len(); add(&mut probes, &format!("ab.-pattern+.com len{}", n), v); }
    { let mut v = rep(b"a.", 254); v.push(b'a'); add(&mut probes, "a. x127 + a len255", v); }
    { let mut v = rep(b"a.", 256); add(&mut probes, "a. x128 len256", v); }
    { let mut v = rep(b"-.", 254); v.push(b'-'); add(&mut probes, "-. pattern len255", v); }
    { let mut v = rep(b"-.", 256); add(&mut probes, "-. pattern len256", v); }

    let total = probes.len();
    let mut fails = 0;
    for (name, arg) in &probes {
        let out = Command::new(bin).arg(OsString::from_vec(arg.clone())).output().expect("spawn");
        let exp = predict(arg);
        if out.stdout != exp || !out.status.success() || !out.stderr.is_empty() {
