            let b: Vec<&[u8]> = exp.split(|&b| b==b'\n').collect();
            for i in 0..a.len().max(b.len()) {
                let av = a.get(i).map(|x| desc(x)).unwrap_or("<missing>".into());
                let bv = b.get(i).map(|x| desc(x)).unwrap_or("<missing>".into());
                if av != bv { println!("  line{}: actual={} predicted={}", i+1, av, bv); }
            }
        }
    }
    println!("PROBES={} FAILS={}", total, fails);
}
