fn rep(b:&[u8],n:usize)->Vec<u8>{ b.iter().cloned().cycle().take(n).collect() }

fn main(){
    let bin="/workspace/dataset/test12_executable";
    let mut fails=0; let mut n=0;
    let mut check=|args:Vec<Vec<u8>>, envs:Vec<(&str,&str)>, label:&str, fails:&mut i32, n:&mut i32|{
        let mut c=Command::new(bin);
        for a in &args { c.arg(OsString::from_vec(a.clone())); }
        for (k,v) in &envs { c.env(k,v); }
        let out=match c.output(){Ok(o)=>o,Err(e)=>{println!("SKIP [{}] {}",label,e);return;}};
        *n+=1;
        let d: &[u8] = if args.is_empty(){ b"multi.level.domain.name.test" } else { &args[0] };
        let exp=predict(d);
        if out.stdout!=exp||!out.status.success()||!out.stderr.is_empty(){
            *fails+=1;
            println!("FAIL [{}] argv1={} status={:?} stderr={}",label,desc(d),out.status.code(),String::from_utf8_lossy(&out.stderr));
            let a:Vec<&[u8]>=out.stdout.split(|&b|b==b'\n').collect(); let b:Vec<&[u8]>=exp.split(|&b|b==b'\n').collect();
            for i in 0..a.len().max(b.len()){ let av=a.get(i).map(|x|desc(x)).unwrap_or("<missing>".into()); let bv=b.get(i).map(|x|desc(x)).unwrap_or("<missing>".into());
                if av!=bv{println!("  line{}: actual={} predicted={}",i+1,av,bv);} }
        }
    };

    // A) locale environments: does to_lower touch >=0x80 (Latin-1 uppercase) or Turkish I?
    let latin1_upper: Vec<u8> = (0xC0u16..=0xDE).map(|b| b as u8).collect(); // 31 bytes
    let mut l255 = rep(&latin1_upper,255);
    let mut l256 = rep(&latin1_upper,256);
    for (lk,lv) in [("LC_ALL","C"),("LC_ALL","C.UTF-8"),("LC_ALL","en_US.UTF-8"),("LC_ALL","tr_TR.UTF-8"),("LC_ALL","de_DE.ISO-8859-1"),("LANG","tr_TR.UTF-8"),("LC_CTYPE","en_US.ISO-8859-1")] {
        check(vec![l255.clone()], vec![(lk,lv)], &format!("latin1upper255 {}={}",lk,lv), &mut fails,&mut n);
        check(vec![l256.clone()], vec![(lk,lv)], &format!("latin1upper256 {}={}",lk,lv), &mut fails,&mut n);
        check(vec![rep(b"ABCIiJ.",255)], vec![(lk,lv)], &format!("ABCIiJ255 {}={}",lk,lv), &mut fails,&mut n);
    }
    l255.truncate(0); l256.truncate(0);

    // B) extra args ignored, incl. huge argv[2]
    check(vec![rep(b"a",255), rep(b"b",300)], vec![], "255a + argv2=300b", &mut fails,&mut n);
    check(vec![rep(b"a",256), rep(b"b",10)], vec![], "256a + argv2=10b", &mut fails,&mut n);
    check(vec![rep(b"a",255), rep(b"b",100000)], vec![], "255a + argv2=100000b", &mut fails,&mut n);
    check(vec![vec![], rep(b"b",255)], vec![], "empty argv1 + argv2", &mut fails,&mut n);
    check(vec![rep(b"a",255), vec![], vec![], rep(b"c",256)], vec![], "255a + 3 extra", &mut fails,&mut n);
    check(vec![b"--help".to_vec()], vec![], "--help", &mut fails,&mut n);
    check(vec![b"-h".to_vec()], vec![], "-h", &mut fails,&mut n);
    check(vec![rep(b"-",255)], vec![], "hyphen255", &mut fails,&mut n);
    check(vec![rep(b"-",256)], vec![], "hyphen256", &mut fails,&mut n);
    check(vec![], vec![], "no args (default)", &mut fails,&mut n);

    // C) huge inputs: other lines must remain correct
    for len in [100000usize, 131071, 131070, 65536, 32768, 20000] {
        check(vec![rep(b"Ab.",len)], vec![], &format!("Ab. huge len{}",len), &mut fails,&mut n);
    }
    check(vec![rep(b".",100000)], vec![], "dots x100000", &mut fails,&mut n);
    { let mut v=rep(b"x",99990); v.extend_from_slice(b".TLD"); check(vec![v],vec![],"huge + .TLD",&mut fails,&mut n); }
    { let mut v=rep(&[0xC3u8,0xA9],100000); v.push(b'.'); check(vec![v],vec![],"huge eacute + trailing dot",&mut fails,&mut n); }
    { let v=rep(&[0xFFu8],131071); check(vec![v],vec![],"0xFF x131071",&mut fails,&mut n); }
    { let v=rep(b" ",131071); check(vec![v],vec![],"space x131071",&mut fails,&mut n); }
    { let v=rep(b"\n",50000); check(vec![v],vec![],"newline x50000",&mut fails,&mut n); }

    // D) determinism: same boundary inputs repeated
    for i in 0..12 {
        check(vec![rep(b"a",256)], vec![], &format!("repeat256 #{}",i), &mut fails,&mut n);
        check(vec![rep(b"a",255)], vec![], &format!("repeat255 #{}",i), &mut fails,&mut n);
    }

    // E) boundary with every possible single filler byte (1..255) at len 255 and 256
    for b in 1u16..=255 {
        let by=b as u8;
        check(vec![rep(&[by],255)], vec![], &format!("byte{:#04x} x255",by), &mut fails,&mut n);
        check(vec![rep(&[by],256)], vec![], &format!("byte{:#04x} x256",by), &mut fails,&mut n);
    }
    println!("PROBES={} FAILS={}",n,fails);
}
